mapper.select:
SELECT id, workspace_id, message_id, `desc`, prompt_tokens, completion_tokens, total_tokens, created_at
FROM code_change_batch
WHERE workspace_id = #{workspaceId}

    AND `desc` LIKE CONCAT('%', #{desc}, '%')


    AND created_at >= #{startTime}


    AND created_at <= #{endTime}

ORDER BY created_at DESC

SELECT id, workspace_id, message_id, `desc`, prompt_tokens, completion_tokens, total_tokens, created_at
FROM code_change_batch
WHERE id = #{batchId}
